import { NavigationContainer } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { Ionicons } from "@expo/vector-icons";
import { HomeScreen } from "./screens/HomeScreen";
import { RecipeDetailScreen } from "./screens/RecipeDetailScreen";
import { useTheme } from "./theme";

export type RootStackParamList = {
  Tabs: undefined;
  RecipeDetail: { recipeId?: string };
};
export type TabParamList = { Recipes: undefined };
const Stack = createNativeStackNavigator<RootStackParamList>();
const Tabs = createBottomTabNavigator<TabParamList>();

function TabsNavigator() {
  const t = useTheme();
  return (
    <Tabs.Navigator screenOptions={{ headerShown: false, tabBarActiveTintColor: t.color.accent, tabBarInactiveTintColor: t.color.muted, tabBarStyle: { backgroundColor: t.color.surface, borderTopColor: t.color.line }, tabBarLabelStyle: { fontSize: 11, fontWeight: "600" } }}>
      <Tabs.Screen name="Recipes" component={HomeScreen} options={{ tabBarIcon: ({ color, size }) => <Ionicons name="book-outline" size={size} color={color} /> }} />
    </Tabs.Navigator>
  );
}

export function Navigation() {
  const t = useTheme();
  return (
    <NavigationContainer theme={{ dark: false, colors: { primary: t.color.accent, background: t.color.bg, card: t.color.surface, text: t.color.text, border: t.color.line, notification: t.color.accent }, fonts: { regular: { fontFamily: "System", fontWeight: "400" }, medium: { fontFamily: "System", fontWeight: "500" }, bold: { fontFamily: "System", fontWeight: "700" }, heavy: { fontFamily: "System", fontWeight: "800" } } }}>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        <Stack.Screen name="Tabs" component={TabsNavigator} />
        <Stack.Screen name="RecipeDetail" component={RecipeDetailScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

