import { useCallback, useState } from "react";
import { ActivityIndicator, Pressable, ScrollView, Text, TextInput, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Ionicons } from "@expo/vector-icons";
import { Card, EmptyState, FAB, Screen } from "../components";
import { useTheme } from "../theme";
import { recipeRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import type { RootStackParamList } from "../navigation";

export function HomeScreen() {
  const t = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useFocusEffect(useCallback(() => {
    let active = true;
    seed().then(() => recipeRepository.list()).then((records) => {
      if (active) { setRecipes([...records]); setError(""); }
    }).catch(() => { if (active) setError("Couldn't load your recipes. Please try again."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []));
  const visible = recipes.filter((recipe) => (!favoritesOnly || recipe.favorite) && `${recipe.title} ${recipe.ingredients.join(" ")}`.toLowerCase().includes(query.trim().toLowerCase()));
  const favoriteCount = recipes.filter((recipe) => recipe.favorite).length;
  return (
    <Screen scroll={false} testID="recipes-screen">
      <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ padding: t.space.xl, paddingBottom: 110 }}>
        <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 28 }}>
          <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
            <Ionicons name="restaurant-outline" size={19} color={t.color.accent} />
            <Text style={{ color: t.color.accent, fontSize: 11, fontWeight: "800", letterSpacing: 2 }}>THE RECIPE BOX</Text>
          </View>
          <View style={{ width: 36, height: 36, borderRadius: t.radius.pill, backgroundColor: t.color.surface, borderWidth: 1, borderColor: t.color.line, alignItems: "center", justifyContent: "center" }}>
            <Ionicons name="leaf-outline" size={18} color={t.color.accent} />
          </View>
        </View>
        <Text style={{ fontSize: 38, fontWeight: "800", letterSpacing: -1.5, color: t.color.text }}>Good food,</Text>
        <Text style={{ fontSize: 38, fontWeight: "800", letterSpacing: -1.5, color: t.color.accent }}>kept close.</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.body, lineHeight: 24, marginTop: 10, marginBottom: 26 }}>Your favorite recipes. All in one little box.</Text>
        <Card style={{ marginBottom: 26, padding: 20 }}>
          <View style={{ flexDirection: "row", alignItems: "center", gap: 16 }}>
            <View style={{ backgroundColor: t.color.bg, width: 56, height: 64, borderRadius: 12, justifyContent: "center", alignItems: "center" }}>
              <Ionicons name="book-outline" size={28} color={t.color.accent} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={{ color: t.color.text, fontSize: 17, fontWeight: "700" }}>A collection worth keeping</Text>
              <Text style={{ color: t.color.muted, fontSize: t.type.small, marginTop: 6 }}>{recipes.length} recipes  ·  {favoriteCount} {favoriteCount === 1 ? "favorite" : "favorites"}</Text>
            </View>
          </View>
        </Card>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 10, backgroundColor: t.color.surface, borderRadius: t.radius.card, borderWidth: 1, borderColor: t.color.line, paddingHorizontal: 14, marginBottom: 20 }}>
          <Ionicons name="search-outline" size={20} color={t.color.muted} />
          <TextInput accessibilityLabel="Search recipes or ingredients" testID="recipe-search" placeholder="Search recipes or ingredients" placeholderTextColor={t.color.muted} value={query} onChangeText={setQuery} style={{ flex: 1, color: t.color.text, fontSize: 15, paddingVertical: 15 }} />
          {query ? <Pressable accessibilityLabel="Clear search" onPress={() => setQuery("")} hitSlop={10}><Ionicons name="close-circle" size={19} color={t.color.muted} /></Pressable> : null}
        </View>
        <View style={{ flexDirection: "row", gap: 10, marginBottom: 28 }}>
          {[{ label: "All recipes", selected: !favoritesOnly, value: false }, { label: "Favorites", selected: favoritesOnly, value: true }].map((filter) => (
            <Pressable key={filter.label} accessibilityRole="button" accessibilityState={{ selected: filter.selected }} onPress={() => setFavoritesOnly(filter.value)} style={{ flexDirection: "row", alignItems: "center", gap: 7, paddingVertical: 9, paddingHorizontal: 16, borderRadius: t.radius.pill, backgroundColor: filter.selected ? t.color.accent : t.color.surface, borderWidth: 1, borderColor: filter.selected ? t.color.accent : t.color.line }}>
              {filter.value ? <Ionicons name="heart-outline" size={15} color={filter.selected ? t.color.surface : t.color.muted} /> : null}
              <Text style={{ color: filter.selected ? t.color.surface : t.color.muted, fontWeight: "600", fontSize: 13 }}>{filter.label}</Text>
            </Pressable>
          ))}
        </View>
        <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <Text style={{ color: t.color.text, fontSize: 20, fontWeight: "700", letterSpacing: -0.4 }}>{query ? "Search results" : favoritesOnly ? "Your favorites" : "Your recipes"}</Text>
          <Text style={{ color: t.color.muted, fontSize: 12 }}>{visible.length} {visible.length === 1 ? "recipe" : "recipes"}</Text>
        </View>
        {loading ? <ActivityIndicator color={t.color.accent} /> : error ? <EmptyState title="Something went wrong" body={error} /> : visible.length === 0 ? <EmptyState title={query ? "No recipes found" : favoritesOnly ? "No favorites yet" : "Your box is ready"} body={query ? "Try another title or ingredient." : favoritesOnly ? "Tap the heart on a recipe to keep it here." : "Tap + to add your first recipe."} /> : visible.map((recipe, index) => (
          <Pressable key={recipe.id} accessibilityRole="button" accessibilityLabel={`Open ${recipe.title}`} onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })} style={{ marginBottom: 12 }}>
            <Card style={{ padding: 16 }}>
              <View style={{ flexDirection: "row", alignItems: "center", gap: 14 }}>
                <View style={{ width: 64, height: 78, backgroundColor: t.color.bg, borderRadius: 10, alignItems: "center", justifyContent: "center", gap: 7 }}>
                  <Ionicons name={recipe.title.toLowerCase().includes("pancake") ? "sunny-outline" : recipe.title.toLowerCase().includes("soup") ? "flame-outline" : "restaurant-outline"} size={28} color={t.color.accent} />
                  <Text style={{ color: t.color.muted, fontSize: 9, fontWeight: "600", letterSpacing: 1 }}>RECIPE {String(index + 1).padStart(2, "0")}</Text>
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: t.color.text, fontSize: 17, fontWeight: "700", lineHeight: 23 }} numberOfLines={2}>{recipe.title}</Text>
                  <View style={{ flexDirection: "row", alignItems: "center", marginTop: 10, gap: 5 }}>
                    <Ionicons name="time-outline" size={14} color={t.color.muted} />
                    <Text style={{ color: t.color.muted, fontSize: 12 }}>{recipe.cookingMinutes} min  ·  {recipe.ingredients.length} ingredients</Text>
                  </View>
                </View>
                <View style={{ gap: 20, alignItems: "center" }}>
                  <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={17} color={recipe.favorite ? t.color.accent : t.color.line} />
                  <Ionicons name="chevron-forward" size={17} color={t.color.muted} />
                </View>
              </View>
            </Card>
          </Pressable>
        ))}
        {!loading && visible.length > 0 ? <Text style={{ textAlign: "center", color: t.color.muted, fontSize: 12, marginTop: 16 }}>A little inspiration for your next meal.</Text> : null}
      </ScrollView>
      <FAB testID="add-recipe" onPress={() => navigation.navigate("RecipeDetail", {})} />
    </Screen>
  );
}

