import { type BaseRecord, createRepository, defineCollection } from "./store";

export const schemaVersion = 2;

export interface Recipe extends BaseRecord {
  title: string;
  ingredients: string[];
  cookingMinutes: number;
  favorite: boolean;
}

export const recipeRepository = createRepository(
  defineCollection<Recipe>("recipes", ["title", "ingredients"]),
);

