import { useCallback, useState } from "react";
import { ActivityIndicator, Pressable, ScrollView, Text, TextInput, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Card, EmptyState, FAB, Screen } from "../components";
import { recipeRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

export function RecipesScreen() {
  const t = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useFocusEffect(useCallback(() => {
    let active = true;
    void (async () => {
      try {
        await seed();
        const records = await recipeRepository.list();
        if (active) { setRecipes(records); setError(""); }
      } catch { if (active) setError("Couldn't load your recipes. Please try again."); }
      finally { if (active) setLoading(false); }
    })();
    return () => { active = false; };
  }, []));
  const q = query.trim().toLowerCase();
  const visible = recipes.filter(r => (!favoritesOnly || r.favorite) && (!q || [r.title, ...r.ingredients].some(value => value.toLowerCase().includes(q))));
  return (
    <Screen scroll={false} testID="recipes-screen">
      <ScrollView contentContainerStyle={{ padding: t.space.xl, paddingBottom: 104 }} keyboardShouldPersistTaps="handled">
        <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 26 }}>
