import { recipeRepository } from "./models";

let pending: Promise<void> | undefined;
export function seed(): Promise<void> {
  if (!pending) pending = seedRecipes().catch((error: unknown) => { pending = undefined; throw error; });
  return pending;
}

async function seedRecipes(): Promise<void> {
  if ((await recipeRepository.list()).length > 0) return;
  await recipeRepository.create({
    title: "Lemon & basil pasta",
    ingredients: ["200 g spaghetti", "1 lemon, zest and juice", "A handful of fresh basil", "2 tbsp olive oil", "40 g grated Parmesan", "Salt and black pepper"],
    cookingMinutes: 20, favorite: true, isDemo: true,
  });
  await recipeRepository.create({
    title: "Sunday pancakes",
    ingredients: ["150 g all-purpose flour", "200 ml milk", "1 egg", "1 tsp baking powder", "1 tbsp sugar", "Butter for the pan", "Maple syrup to serve"],
    cookingMinutes: 25, favorite: false, isDemo: true,
  });
  await recipeRepository.create({
    title: "Roasted tomato soup",
    ingredients: ["800 g ripe tomatoes", "1 onion, quartered", "3 garlic cloves", "2 tbsp olive oil", "500 ml vegetable stock", "Fresh basil to serve"],
    cookingMinutes: 45, favorite: false, isDemo: true,
  });
}

