import { useEffect, useState } from "react";
import { ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Button, Card, EmptyState, Screen, TextField } from "../components";
import { recipeRepository, type Recipe } from "../data/models";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

export function RecipeDetailScreen({ navigation, route }: Props) {
  const t = useTheme();
  const id = route.params.recipeId;
  const [recipe, setRecipe] = useState<Recipe>();
  const [loading, setLoading] = useState(Boolean(id));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [title, setTitle] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [minutes, setMinutes] = useState("");
  const [checked, setChecked] = useState<number[]>([]);
  useEffect(() => {
    if (!id) return;
    let active = true;
    void recipeRepository.get(id).then(value => {
      if (active) { setRecipe(value); if (!value) setError("This recipe could not be found."); }
    }).catch(() => { if (active) setError("Couldn't load this recipe. Please try again."); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [id]);

  async function save() {
    const list = ingredients.split("\n").map(item => item.trim()).filter(Boolean);
    const cookingMinutes = Number(minutes);
    if (!title.trim() || list.length === 0 || !Number.isInteger(cookingMinutes) || cookingMinutes < 1 || cookingMinutes > 10080) {
      setError("Add a title, at least one ingredient, and cooking minutes from 1 to 10,080.");
      return;
    }
    setBusy(true); setError("");
    try {
      const created = await recipeRepository.create({ title: title.trim(), ingredients: list, cookingMinutes, favorite: false });
      setRecipe(created);
      navigation.setParams({ recipeId: created.id });
    } catch { setError("Couldn't save your recipe. Please try again."); }
    finally { setBusy(false); }
  }

  async function toggleFavorite() {
    if (!recipe || busy) return;
    setBusy(true); setError("");
    try { setRecipe(await recipeRepository.update(recipe.id, { favorite: !recipe.favorite })); }
    catch { setError("Couldn't update your favorite. Please try again."); }
    finally { setBusy(false); }
  }

  return (
    <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
      <Screen testID="recipe-detail-screen">
        <View style={{ paddingHorizontal: 8 }}>
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 30, marginTop: 8 }}>
            <Pressable accessibilityRole="button" accessibilityLabel="Back to recipes" onPress={() => navigation.goBack()} style={{ flexDirection: "row", gap: 7, alignItems: "center", paddingVertical: 8 }}>
              <Ionicons name="arrow-back" size={21} color={t.color.text} />
              <Text style={{ color: t.color.text, fontSize: 14, fontWeight: "600" }}>Recipes</Text>
            </Pressable>
            <Text style={{ color: t.color.muted, fontSize: 10, letterSpacing: 1.5, fontWeight: "700" }}>{id ? "RECIPE BOX" : "NEW RECIPE"}</Text>
          </View>
          {loading ? <ActivityIndicator color={t.color.accent} /> : !id ? (
            <View>
              <Text style={{ color: t.color.accent, letterSpacing: 2, fontSize: 11, fontWeight: "700", marginBottom: 12 }}>MAKE IT YOURS</Text>
              <Text style={{ fontSize: 34, color: t.color.text, fontWeight: "800", letterSpacing: -1, marginBottom: 8 }}>A new favorite.</Text>
              <Text style={{ color: t.color.muted, fontSize: 15, lineHeight: 22, marginBottom: 28 }}>Keep the recipes you come back to, all in one place.</Text>
              <Card style={{ marginBottom: 20 }}>
                <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title" />
                <TextField label="Cooking time (minutes)" value={minutes} onChangeText={setMinutes} testID="recipe-minutes" />
                <TextField label="Ingredients · one per line" value={ingredients} onChangeText={setIngredients} multiline testID="recipe-ingredients" />
                <Text style={{ color: t.color.muted, fontSize: 12, lineHeight: 18 }}>Include quantities, too. For example: 200 g spaghetti.</Text>
              </Card>
              {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: 16, lineHeight: 20 }}>{error}</Text> : null}
              <Button label={busy ? "Saving…" : "Save recipe"} onPress={() => { void save(); }} disabled={busy} testID="save-recipe" />
            </View>
          ) : recipe ? (
            <View>
              <Card style={{ backgroundColor: t.color.accent, borderColor: t.color.accent, height: 170, alignItems: "center", justifyContent: "center", marginBottom: 28, overflow: "hidden" }}>
                <View style={{ position: "absolute", width: 230, height: 230, borderRadius: 115, borderWidth: 1, borderColor: t.color.surface, opacity: 0.18 }} />
                <View style={{ position: "absolute", width: 140, height: 140, borderRadius: 70, borderWidth: 1, borderColor: t.color.surface, opacity: 0.25 }} />
                <Ionicons name={recipe.title.toLowerCase().includes("soup") ? "flame-outline" : recipe.title.toLowerCase().includes("pancake") ? "sunny-outline" : "leaf-outline"} size={64} color={t.color.surface} />
                <Text style={{ color: t.color.surface, opacity: 0.8, fontSize: 10, letterSpacing: 2, marginTop: 15 }}>A LITTLE HOMEMADE GOODNESS</Text>
              </Card>
              <Text style={{ color: t.color.muted, fontSize: 10, fontWeight: "700", letterSpacing: 2, marginBottom: 10 }}>{recipe.isDemo ? "FROM THE DEMO COLLECTION" : "FROM YOUR KITCHEN"}</Text>
              <Text style={{ color: t.color.text, fontSize: 34, fontWeight: "800", letterSpacing: -1, lineHeight: 39 }}>{recipe.title}</Text>
              <View style={{ flexDirection: "row", gap: 16, alignItems: "center", marginTop: 18, marginBottom: 24 }}>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
                  <Ionicons name="time-outline" size={18} color={t.color.accent} />
                  <Text style={{ fontSize: 13, color: t.color.muted }}>{recipe.cookingMinutes} minutes</Text>
                </View>
                <View style={{ width: 1, height: 16, backgroundColor: t.color.line }} />
                <Text style={{ fontSize: 13, color: t.color.muted }}>{recipe.ingredients.length} ingredients</Text>
              </View>
              <Pressable testID="toggle-favorite" accessibilityRole="button" accessibilityLabel={recipe.favorite ? "Remove from favorites" : "Add to favorites"} accessibilityState={{ selected: recipe.favorite, disabled: busy }} disabled={busy} onPress={() => { void toggleFavorite(); }} style={{ flexDirection: "row", justifyContent: "center", alignItems: "center", gap: 9, padding: 14, borderRadius: t.radius.card, borderWidth: 1, borderColor: recipe.favorite ? t.color.accent : t.color.line, backgroundColor: t.color.surface, opacity: busy ? 0.5 : 1, marginBottom: 30 }}>
                <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={19} color={t.color.accent} />
                <Text style={{ color: t.color.accent, fontWeight: "600", fontSize: 14 }}>{recipe.favorite ? "Saved to favorites" : "Add to favorites"}</Text>
              </Pressable>
              {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: 16 }}>{error}</Text> : null}
              <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <Text style={{ color: t.color.text, fontSize: 22, fontWeight: "700", letterSpacing: -0.5 }}>Ingredients</Text>
                <Text style={{ color: t.color.muted, fontSize: 12 }}>{checked.length} / {recipe.ingredients.length}</Text>
              </View>
              <Text style={{ color: t.color.muted, fontSize: 12, marginBottom: 18 }}>Tap to check off as you prep.</Text>
              <Card style={{ paddingVertical: 4, marginBottom: 24 }}>
                {recipe.ingredients.map((ingredient, index) => {
                  const done = checked.includes(index);
                  return (
                    <Pressable key={`${index}-${ingredient}`} accessibilityRole="checkbox" accessibilityState={{ checked: done }} accessibilityLabel={ingredient} onPress={() => setChecked(previous => done ? previous.filter(item => item !== index) : [...previous, index])} style={{ flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 16, borderBottomWidth: index === recipe.ingredients.length - 1 ? 0 : 1, borderColor: t.color.line }}>
                      <Ionicons name={done ? "checkmark-circle" : "ellipse-outline"} size={22} color={done ? t.color.accent : t.color.line} />
                      <Text style={{ flex: 1, color: done ? t.color.muted : t.color.text, fontSize: 15, lineHeight: 21, textDecorationLine: done ? "line-through" : "none" }}>{ingredient}</Text>
                    </Pressable>
                  );
                })}
              </Card>
              <Text style={{ textAlign: "center", color: t.color.muted, fontSize: 12, marginBottom: 20 }}>Something good starts here.</Text>
            </View>
          ) : <EmptyState title="Recipe unavailable" body={error} />}
        </View>
      </Screen>
    </KeyboardAvoidingView>
  );
}

