import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Ionicons } from '@expo/vector-icons';
import { HomeScreen } from './screens/HomeScreen';
import { RecipeDetailScreen } from './screens/RecipeDetailScreen';
import { useTheme } from './theme';

export type RootStackParamList = { Tabs: undefined; RecipeDetail: { id?: string } };
const Stack = createNativeStackNavigator<RootStackParamList>();
const Tabs = createBottomTabNavigator();
function TabsNavigator() {
  const t = useTheme();
  return <Tabs.Navigator screenOptions={{ headerShown: false, tabBarActiveTintColor: t.color.accent, tabBarInactiveTintColor: t.color.muted, tabBarStyle: { backgroundColor: t.color.surface, borderTopColor: t.color.line }, tabBarLabelStyle: { fontSize: t.type.small, fontWeight: '600' } }}>
    <Tabs.Screen name="Recipes" component={HomeScreen} options={{ tabBarIcon: ({ color, size }) => <Ionicons name="book-outline" color={color} size={size} /> }} />
  </Tabs.Navigator>;
}
export function Navigation() {
  const t = useTheme();
  return <NavigationContainer theme={{ ...DefaultTheme, colors: { ...DefaultTheme.colors, primary: t.color.accent, background: t.color.bg, card: t.color.surface, text: t.color.text, border: t.color.line } }}>
    <Stack.Navigator screenOptions={{ headerShown: false }}>
      <Stack.Screen name="Tabs" component={TabsNavigator} />
      <Stack.Screen name="RecipeDetail" component={RecipeDetailScreen} />
    </Stack.Navigator>
  </NavigationContainer>;
}

