        <Ionicons name="search-outline" size={20} color={t.color.muted} />
        <TextInput testID="recipe-search" accessibilityLabel="Search recipes or ingredients" placeholder="Search recipes or ingredients" placeholderTextColor={t.color.muted} value={query} onChangeText={setQuery} style={{ flex: 1, color: t.color.text, fontSize: t.type.body, padding: t.space.md }} />
        {!!query && <Pressable accessibilityLabel="Clear search" onPress={() => setQuery('')} hitSlop={10}><Ionicons name="close-circle" size={20} color={t.color.muted} /></Pressable>}
