        {[false, true].map(value => <Pressable key={String(value)} accessibilityRole="button" accessibilityState={{ selected: favorites === value }} onPress={() => setFavorites(value)} style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingHorizontal: t.space.lg, paddingVertical: 10, borderRadius: t.radius.pill, backgroundColor: favorites === value ? t.color.text : t.color.surface, borderWidth: 1, borderColor: favorites === value ? t.color.text : t.color.line }}>
          {value && <Ionicons name="heart-outline" size={16} color={favorites === value ? t.color.surface : t.color.muted} />}
          <Text style={{ color: favorites === value ? t.color.surface : t.color.muted, fontWeight: '600', fontSize: t.type.small }}>{value ? 'Favorites' : 'All recipes'}</Text>
        </Pressable>)}
      </View>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: t.space.md }}>
        <Text style={{ color: t.color.muted, fontWeight: '600', letterSpacing: 1.5, fontSize: 11 }}>{favorites ? 'YOUR FAVORITES' : 'YOUR COLLECTION'}</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.small }}>{filtered.length} {filtered.length === 1 ? 'recipe' : 'recipes'}</Text>
      </View>
      {loading ? <ActivityIndicator color={t.color.accent} /> : error ? <EmptyState title="Something went wrong" body={error} /> : filtered.length === 0 ? <EmptyState title={query ? 'No recipes found' : favorites ? 'Save your favorites' : 'Start your recipe box'} body={query ? 'Try a different title or ingredient.' : favorites ? 'Tap the heart on a recipe to keep it here.' : 'Tap + to add your first recipe.'} /> : filtered.map((recipe, index) => <Pressable key={recipe.id} accessibilityRole="button" accessibilityLabel={`Open ${recipe.title}`} onPress={() => navigation.navigate('RecipeDetail', { id: recipe.id })} style={{ marginBottom: t.space.md }}>
        <Card>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: t.space.md }}>
            <View style={{ width: 60, height: 72, borderRadius: t.radius.card, backgroundColor: t.color.bg, alignItems: 'center', justifyContent: 'center' }}>
              <Ionicons name={recipe.title.toLowerCase().includes('soup') ? 'flame-outline' : recipe.title.toLowerCase().includes('pancake') ? 'cafe-outline' : 'restaurant-outline'} size={28} color={t.color.accent} />
