export function RecipeDetailScreen({ route, navigation }: Props) {
  const t = useTheme();
  const id = route.params.id;
  const [recipe, setRecipe] = useState<Recipe>();
  const [loading, setLoading] = useState(!!id);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [title, setTitle] = useState('');
  const [ingredients, setIngredients] = useState('');
  const [minutes, setMinutes] = useState('');
  useEffect(() => {
    let active = true;
    if (id) recipes.get(id).then(result => { if (active) setRecipe(result); }).catch(() => { if (active) setError('Could not load this recipe.'); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [id]);
  async function save() {
    const lines = ingredients.split('\n').map(line => line.trim()).filter(Boolean);
    const duration = Number(minutes);
    if (!title.trim() || !lines.length || !minutes.trim() || !Number.isInteger(duration) || duration < 1) {
      setError('Add a title, at least one ingredient, and cooking time in whole minutes (1 or more).');
      return;
    }
    setBusy(true); setError('');
    try {
      const created = await recipes.create({ title: title.trim(), ingredients: lines, cookingMinutes: duration, favorite: false });
      setRecipe(created);
      navigation.setParams({ id: created.id });
    } catch { setError('Could not save your recipe. Please try again.'); }
    finally { setBusy(false); }
  }
  async function toggleFavorite() {
    if (!recipe || busy) return;
    setBusy(true); setError('');
    try { setRecipe(await recipes.update(recipe.id, { favorite: !recipe.favorite })); }
