        <Ionicons name={recipe.favorite ? 'heart' : 'heart-outline'} size={24} color={t.color.accent} />
      </Pressable>}
    </View>
    {loading ? <ActivityIndicator color={t.color.accent} /> : !id ? <View>
      <Text style={{ color: t.color.accent, fontSize: 11, fontWeight: '700', letterSpacing: 2, marginBottom: t.space.md }}>A NEW DISCOVERY</Text>
