import { NavigationContainer } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { Ionicons } from "@expo/vector-icons";
import { HomeScreen } from "./screens/HomeScreen";
import { RecipeDetailScreen } from "./screens/RecipeDetailScreen";
import { useTheme } from "./theme";

export type RootStackParamList = {
  Tabs: undefined;
  RecipeDetail: { recipeId?: string };
};
export type TabParamList = { Recipes: undefined };
const Stack = createNativeStackNavigator<RootStackParamList>();
const Tabs = createBottomTabNavigator<TabParamList>();

function TabsNavigator() {
  const t = useTheme();
  return (
    <Tabs.Navigator screenOptions={{ headerShown: false, tabBarActiveTintColor: t.color.accent, tabBarInactiveTintColor: t.color.muted, tabBarStyle: { backgroundColor: t.color.surface, borderTopColor: t.color.line }, tabBarLabelStyle: { fontSize: t.type.small, fontWeight: "600" } }}>
      <Tabs.Screen name="Recipes" component={HomeScreen} options={{ tabBarIcon: ({ color, size }) => <Ionicons name="book-outline" color={color} size={size} /> }} />
    </Tabs.Navigator>
  );
}

export function Navigation() {
  const t = useTheme();
  return (
    <NavigationContainer>
      <Stack.Navigator screenOptions={{ headerStyle: { backgroundColor: t.color.bg }, headerTintColor: t.color.text, headerShadowVisible: false, contentStyle: { backgroundColor: t.color.bg } }}>
        <Stack.Screen name="Tabs" component={TabsNavigator} options={{ headerShown: false }} />
        <Stack.Screen name="RecipeDetail" component={RecipeDetailScreen} options={({ route }) => ({ title: route.params.recipeId ? "Recipe detail" : "New recipe" })} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

