        if (active) { setRecipes(items); setError(""); }
      } catch { if (active) setError("Couldn't load your recipes. Please try again."); }
      finally { if (active) setLoading(false); }
    }
    void load();
    return () => { active = false; };
  }, []));
  const favoriteCount = recipes.filter(r => r.favorite).length;
  const normalized = query.trim().toLowerCase();
  const visible = recipes.filter(r => (!favoritesOnly || r.favorite) && [r.title, ...r.ingredients].some(value => value.toLowerCase().includes(normalized)));

  return (
    <Screen scroll={false} testID="recipes-screen">
