        </View>
        <Text style={{ color: t.color.text, fontSize: 38, fontWeight: "700", letterSpacing: -1.5 }}>Recipe box</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.body, marginTop: t.space.sm, lineHeight: 24 }}>Good food. Kept close.</Text>
        <View style={{ flexDirection: "row", alignItems: "center", gap: t.space.sm, marginTop: t.space.lg, marginBottom: t.space.xl }}>
          <Text style={{ color: t.color.text, fontWeight: "600", fontSize: t.type.small }}>{recipes.length} recipes</Text>
          <Text style={{ color: t.color.line }}>•</Text>
          <Ionicons name="heart" size={13} color={t.color.accent} />
