                    <Ionicons name="time-outline" size={13} color={t.color.muted} />
                    <Text style={{ color: t.color.muted, fontSize: 12 }}>{recipe.cookingMinutes} min  ·  {recipe.ingredients.length} ingredients</Text>
                  </View>
                </View>
                <Ionicons name={recipe.favorite ? "heart" : "chevron-forward"} size={18} color={recipe.favorite ? t.color.accent : t.color.muted} />
              </View>
            </Card>
          </Pressable>
        ))}
        {!loading && !query && !favoritesOnly && recipes.length > 0 ? <Text style={{ textAlign: "center", color: t.color.muted, fontSize: 12, marginTop: t.space.lg }}>A home for your tried-and-loved recipes.</Text> : null}
      </ScrollView>
      <FAB testID="add-recipe" onPress={() => navigation.navigate("RecipeDetail", {})} />
    </Screen>
  );
}

