    { title: "Sunday pancakes", ingredients: ["150 g all-purpose flour", "1 egg", "200 ml milk", "1 tsp baking powder", "1 tbsp sugar", "Butter, for the pan", "Maple syrup, to serve"], cookingMinutes: 15, favorite: false },
