import { recipeRepository } from "./models";

let pending: Promise<void> | undefined;
export function seed(): Promise<void> {
  if (!pending) pending = seedRecipes().catch((error: unknown) => { pending = undefined; throw error; });
  return pending;
}

async function seedRecipes(): Promise<void> {
  const existing = await recipeRepository.list();
  const demos = [
    { title: "Lemon & basil pasta", ingredients: ["200 g spaghetti", "1 lemon, zest and juice", "2 tbsp olive oil", "1 handful fresh basil", "40 g grated Parmesan", "Salt and black pepper"], cookingMinutes: 20, favorite: true },
    { title: "Fluffy Sunday pancakes", ingredients: ["150 g all-purpose flour", "1 tbsp sugar", "1 tsp baking powder", "1 egg", "180 ml milk", "1 tbsp melted butter", "Maple syrup, to serve"], cookingMinutes: 25, favorite: false },
    { title: "Roasted tomato soup", ingredients: ["6 ripe tomatoes, halved", "1 onion, chopped", "3 garlic cloves", "2 tbsp olive oil", "500 ml vegetable stock", "Fresh basil, to serve"], cookingMinutes: 45, favorite: false },
  ];
  for (const recipe of demos) {
    if (!existing.some((record) => record.isDemo && record.title === recipe.title)) {
      await recipeRepository.create({ ...recipe, isDemo: true });
    }
  }
}

