import { useEffect, useState } from "react";
import { ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Ionicons } from "@expo/vector-icons";
import { Button, Card, EmptyState, Screen, TextField } from "../components";
import { useTheme } from "../theme";
import { recipeRepository, type Recipe } from "../data/models";
import type { RootStackParamList } from "../navigation";

type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

export function RecipeDetailScreen({ route, navigation }: Props) {
  const t = useTheme();
  const id = route.params.id;
  const [recipe, setRecipe] = useState<Recipe>();
  const [loading, setLoading] = useState(!!id);
  const [title, setTitle] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [minutes, setMinutes] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    if (!id) return;
    let active = true;
    recipeRepository.get(id).then((record) => {
      if (active) { setRecipe(record); setLoading(false); }
    }).catch(() => { if (active) { setError("Couldn't load this recipe."); setLoading(false); } });
    return () => { active = false; };
  }, [id]);

  async function save() {
    const items = ingredients.split("\n").map((item) => item.trim()).filter(Boolean);
    const cookingMinutes = Number(minutes);
    if (!title.trim() || items.length === 0 || !Number.isInteger(cookingMinutes) || cookingMinutes <= 0) {
      setError("Add a title, at least one ingredient, and a cooking time in whole minutes greater than zero.");
      return;
    }
    setBusy(true); setError("");
    try {
      const created = await recipeRepository.create({ title: title.trim(), ingredients: items, cookingMinutes, favorite: false });
      navigation.replace("RecipeDetail", { id: created.id });
    } catch { setError("Couldn't save your recipe. Please try again."); }
    finally { setBusy(false); }
  }

  async function toggleFavorite() {
    if (!recipe || busy) return;
    setBusy(true); setError("");
    try { setRecipe(await recipeRepository.update(recipe.id, { favorite: !recipe.favorite })); }
    catch { setError("Couldn't update your favorite. Please try again."); }
    finally { setBusy(false); }
  }

  if (!id) return (
    <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
      <Screen testID="new-recipe-screen">
        <View style={{ padding: t.space.sm }}>
          <Text style={{ color: t.color.accent, fontSize: t.type.small, letterSpacing: 2, fontWeight: "700", marginBottom: t.space.md }}>SOMETHING DELICIOUS</Text>
          <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "700", marginBottom: t.space.sm }}>Add to your box</Text>
          <Text style={{ color: t.color.muted, fontSize: t.type.body, lineHeight: 24, marginBottom: t.space.xl }}>Keep a new discovery or a family favorite for another day.</Text>
          <Card style={{ marginBottom: t.space.xl }}>
            <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title" />
            <TextField label="Cooking time (minutes)" value={minutes} onChangeText={setMinutes} testID="recipe-minutes" />
            <TextField label="Ingredients · one per line" value={ingredients} onChangeText={setIngredients} multiline testID="recipe-ingredients" />
            <Text style={{ color: t.color.muted, fontSize: t.type.small }}>Include quantities, e.g. 200 g spaghetti.</Text>
          </Card>
          {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: t.space.lg }}>{error}</Text> : null}
          <Button label={busy ? "Saving…" : "Save recipe"} onPress={() => void save()} disabled={busy} testID="save-recipe" />
          <Pressable accessibilityRole="button" onPress={() => navigation.goBack()} style={{ padding: t.space.lg, alignItems: "center" }}><Text style={{ color: t.color.muted }}>Cancel</Text></Pressable>
        </View>
      </Screen>
    </KeyboardAvoidingView>
  );

  if (loading) return <Screen><ActivityIndicator color={t.color.accent} /></Screen>;
  if (!recipe) return <Screen><EmptyState title="Recipe unavailable" body={error || "This recipe could not be found."} /><Button label="Back to recipes" onPress={() => navigation.goBack()} /></Screen>;
  return (
    <Screen testID="recipe-detail-screen">
      <View style={{ padding: t.space.sm }}>
        <Card style={{ alignItems: "center", paddingVertical: 32, marginBottom: t.space.xl }}>
          <View style={{ borderRadius: t.radius.pill, backgroundColor: t.color.bg, padding: t.space.xl, marginBottom: t.space.lg }}><Ionicons name="restaurant-outline" size={46} color={t.color.accent} /></View>
          <Text style={{ color: t.color.accent, fontSize: t.type.small, letterSpacing: 2, fontWeight: "700", marginBottom: t.space.md }}>FROM YOUR RECIPE BOX</Text>
          <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "700", textAlign: "center", lineHeight: 35, marginBottom: t.space.lg }}>{recipe.title}</Text>
          <View style={{ flexDirection: "row", alignItems: "center", gap: t.space.sm }}>
            <Ionicons name="time-outline" size={18} color={t.color.muted} />
            <Text style={{ color: t.color.muted, fontSize: t.type.body }}>{recipe.cookingMinutes} minutes</Text>
            <Text style={{ color: t.color.line, marginHorizontal: t.space.sm }}>|</Text>
            <Text style={{ color: t.color.muted, fontSize: t.type.body }}>{recipe.ingredients.length} ingredients</Text>
          </View>
        </Card>
        <Pressable accessibilityRole="button" accessibilityLabel={recipe.favorite ? "Remove from favorites" : "Add to favorites"} accessibilityState={{ selected: recipe.favorite, disabled: busy }} disabled={busy} onPress={() => void toggleFavorite()} testID="toggle-favorite" style={{ flexDirection: "row", gap: t.space.sm, justifyContent: "center", alignItems: "center", padding: t.space.md, borderWidth: 1, borderColor: recipe.favorite ? t.color.accent : t.color.line, borderRadius: t.radius.card, backgroundColor: t.color.surface, marginBottom: 32, opacity: busy ? 0.5 : 1 }}>
          <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={21} color={t.color.accent} />
          <Text style={{ color: t.color.accent, fontSize: t.type.body, fontWeight: "600" }}>{recipe.favorite ? "Saved to favorites" : "Add to favorites"}</Text>
        </Pressable>
        {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: t.space.lg }}>{error}</Text> : null}
        <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: t.space.lg }}>
          <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "700" }}>Ingredients</Text>
          <Text style={{ color: t.color.muted, fontSize: t.type.small }}>{recipe.ingredients.length} items</Text>
        </View>
        <Card>
          {recipe.ingredients.map((ingredient, index) => (
            <View key={`${index}-${ingredient}`} style={{ flexDirection: "row", alignItems: "center", paddingVertical: t.space.lg, gap: t.space.md, borderBottomWidth: index === recipe.ingredients.length - 1 ? 0 : 1, borderColor: t.color.line }}>
              <View style={{ width: 7, height: 7, borderRadius: t.radius.pill, backgroundColor: t.color.accent }} />
              <Text style={{ color: t.color.text, fontSize: t.type.body, lineHeight: 23, flex: 1 }}>{ingredient}</Text>
            </View>
          ))}
        </Card>
        <Text style={{ color: t.color.muted, fontSize: t.type.small, textAlign: "center", marginVertical: t.space.xl }}>A recipe worth keeping. A meal worth sharing.</Text>
      </View>
    </Screen>
  );
}

