  const loadRecipes = useCallback(async () => {
    const next = query.trim() ? await recipesRepo.search(query) : await recipesRepo.list();
    setRecipes(next);
  }, [query]);

  useEffect(() => {
    void loadRecipes();
  }, [loadRecipes]);

  const canSave = useMemo(() => {
    return title.trim().length > 0 && ingredientsText.trim().length > 0 && Number(minutes) > 0;
  }, [title, ingredientsText, minutes]);

  const saveRecipe = useCallback(async () => {
    const parsedMinutes = Number(minutes);
    if (!canSave || Number.isNaN(parsedMinutes)) return;

    const ingredients = ingredientsText
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0);

    await recipesRepo.create({
      title: title.trim(),
      ingredients,
      cookingMinutes: parsedMinutes,
      favorite: false,
    });

    setTitle("");
    setIngredientsText("");
    setMinutes("");
    setShowAdd(false);
    await loadRecipes();
  }, [canSave, ingredientsText, loadRecipes, minutes, title]);

  return (
    <Screen scroll={false}>
      <View style={{ flex: 1, padding: t.space.lg }}>
        <TextField label="Search recipes" value={query} onChangeText={setQuery} />

        {showAdd ? (
          <Card style={{ marginBottom: t.space.md }}>
            <Text style={{ fontSize: t.type.title, color: t.color.text, marginBottom: t.space.md }}>Add Recipe</Text>
            <TextField label="Title" value={title} onChangeText={setTitle} />
            <TextField
              label="Ingredients (one per line)"
              value={ingredientsText}
              onChangeText={setIngredientsText}
              multiline
            />
            <TextField label="Cooking minutes" value={minutes} onChangeText={setMinutes} />
            <View style={{ flexDirection: "row", gap: t.space.sm }}>
              <View style={{ flex: 1 }}>
                <Button label="Save" onPress={() => void saveRecipe()} disabled={!canSave} />
              </View>
              <View style={{ flex: 1 }}>
                <Button label="Cancel" onPress={() => setShowAdd(false)} variant="danger" />
              </View>
            </View>
          </Card>
        ) : null}

        {recipes.length === 0 ? (
          <EmptyState title="No recipes yet" body="Tap + to add your first recipe." />
        ) : (
          <View>
            {recipes.map((recipe) => (
              <ListRow
                key={recipe.id}
                title={recipe.title}
                subtitle={`${recipe.cookingMinutes} min${recipe.favorite ? " • ★ Favorite" : ""}`}
                onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}
              />
            ))}
          </View>
        )}
      </View>
      <FAB onPress={() => setShowAdd((v) => !v)} />
    </Screen>
  );
}

