import { useEffect, useMemo, useState } from "react";
import { Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Button, Card, Screen, TextField } from "../components";
import { useTheme } from "../theme";
import type { RootStackParamList } from "../navigation";
import { createRepository } from "../data/store";
import { recipesCollection } from "../data/models";

const recipesRepo = createRepository(recipesCollection);

type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

export function RecipeDetailScreen({ route, navigation }: Props) {
  const t = useTheme();
  const recipeId = route.params?.recipeId;
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");
  const [isFavorite, setIsFavorite] = useState(false);

  useEffect(() => {
    async function load() {
      if (!recipeId) return;
      const recipe = await recipesRepo.get(recipeId);
      if (!recipe) return;
      setTitle(recipe.title);
      setIngredientsText(recipe.ingredients.join("\n"));
      setMinutesText(String(recipe.cookingMinutes));
      setIsFavorite(recipe.isFavorite);
    }
    void load();
  }, [recipeId]);

  const parsedIngredients = useMemo(
    () => ingredientsText.split("\n").map((i) => i.trim()).filter(Boolean),
    [ingredientsText],
  );

  const parsedMinutes = Number(minutesText);
  const isValid = title.trim().length > 0 && parsedIngredients.length > 0 && Number.isFinite(parsedMinutes) && parsedMinutes > 0;

  async function onSave() {
    const input = {
      title: title.trim(),
      ingredients: parsedIngredients,
      cookingMinutes: parsedMinutes,
      isFavorite,
    };

    if (recipeId) {
      await recipesRepo.update(recipeId, input);
    } else {
      await recipesRepo.create(input);
    }
    navigation.goBack();
  }

  async function onToggleFavorite() {
    if (!recipeId) {
      setIsFavorite((prev) => !prev);
      return;
    }
    const updated = await recipesRepo.update(recipeId, { isFavorite: !isFavorite });
    setIsFavorite(updated.isFavorite);
  }

  return (
    <Screen>
      <Card>
        <Text style={{ fontSize: t.type.title, color: t.color.text, marginBottom: t.space.md }}>{recipeId ? "Recipe detail" : "Add recipe"}</Text>
        <TextField label="Title" value={title} onChangeText={setTitle} />
        <TextField label="Ingredients (one per line)" value={ingredientsText} onChangeText={setIngredientsText} multiline />
        <TextField label="Cooking minutes" value={minutesText} onChangeText={setMinutesText} />
        <View style={{ gap: t.space.sm }}>
          <Button label={isFavorite ? "★ Favorite (tap to unfavorite)" : "☆ Mark favorite"} onPress={onToggleFavorite} />
          <Button label="Save recipe" onPress={onSave} disabled={!isValid} />
        </View>
      </Card>
    </Screen>
  );
}

