import { useCallback, useEffect, useMemo, useState } from "react";
import { Alert, Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Button, Card, EmptyState, FAB, ListRow, Screen, TextField } from "../components";
import { recipesRepo, type Recipe } from "../data/models";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

type Props = NativeStackScreenProps<RootStackParamList, "Tabs">;

export function RecipesScreen({ navigation }: Props) {
  const t = useTheme();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");

  const load = useCallback(async () => {
    const list = query.trim() ? await recipesRepo.search(query) : await recipesRepo.list();
    setRecipes(list);
  }, [query]);

  useEffect(() => {
    void load();
  }, [load]);

  const resetForm = useCallback(() => {
    setTitle("");
    setIngredientsText("");
    setMinutesText("");
  }, []);

  const onAdd = useCallback(async () => {
    const parsedMinutes = Number(minutesText);
    const ingredients = ingredientsText
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean);

    if (!title.trim()) {
      Alert.alert("Missing title", "Please enter a recipe title.");
      return;
    }
    if (!Number.isFinite(parsedMinutes) || parsedMinutes <= 0) {
      Alert.alert("Invalid cooking time", "Please enter cooking minutes as a positive number.");
      return;
    }
    if (ingredients.length === 0) {
      Alert.alert("Missing ingredients", "Add at least one ingredient (one per line).");
      return;
    }

    await recipesRepo.create({
      title: title.trim(),
      ingredients,
      cookingMinutes: parsedMinutes,
      favorite: false,
    });
    resetForm();
    setShowAdd(false);
    await load();
  }, [ingredientsText, load, minutesText, resetForm, title]);

  const sortedRecipes = useMemo(() => {
    return [...recipes].sort((a, b) => Number(b.favorite) - Number(a.favorite) || a.title.localeCompare(b.title));
  }, [recipes]);

  return (
    <Screen scroll={false}>
      <View style={{ flex: 1, padding: t.space.lg }}>
        <TextField label="Search recipes" value={query} onChangeText={setQuery} />

        {showAdd ? (
          <Card style={{ marginBottom: t.space.md }}>
            <Text style={{ fontSize: t.type.title, color: t.color.text, marginBottom: t.space.md }}>Add recipe</Text>
            <TextField label="Title" value={title} onChangeText={setTitle} />
            <TextField
              label="Ingredients (one per line)"
              value={ingredientsText}
              onChangeText={setIngredientsText}
              multiline
            />
            <TextField label="Cooking minutes" value={minutesText} onChangeText={setMinutesText} />
            <View style={{ gap: t.space.sm }}>
              <Button label="Save recipe" onPress={() => void onAdd()} />
              <Button
                label="Cancel"
                onPress={() => {
                  setShowAdd(false);
                  resetForm();
                }}
                variant="danger"
              />
            </View>
          </Card>
        ) : null}

        <View style={{ flex: 1 }}>
          {sortedRecipes.length === 0 ? (
            <EmptyState title="No recipes yet" body="Tap + to add your first recipe." />
          ) : (
            sortedRecipes.map((recipe) => (
              <ListRow
                key={recipe.id}
                title={`${recipe.favorite ? "★ " : ""}${recipe.title}`}
                subtitle={`${recipe.cookingMinutes} min • ${recipe.ingredients.length} ingredients`}
                onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}
              />
            ))
          )}
        </View>

        <FAB onPress={() => setShowAdd((v) => !v)} />
      </View>
    </Screen>
  );
}

