import { useEffect, useMemo, useState } from "react";
import { Alert, Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Button, Card, Screen, TextField } from "../components";
import { useTheme } from "../theme";
import { createRepository } from "../data/store";
import { recipesCollection } from "../data/models";
import type { RootStackParamList } from "../navigation";

type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

const recipesRepo = createRepository(recipesCollection);

export function RecipeDetailScreen({ navigation, route }: Props) {
  const t = useTheme();
  const recipeId = route.params?.recipeId;
  const isEdit = Boolean(recipeId);

  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [cookingMinutesText, setCookingMinutesText] = useState("");
  const [favorite, setFavorite] = useState(false);

  useEffect(() => {
    if (!recipeId) return;
    void (async () => {
      const record = await recipesRepo.get(recipeId);
      if (!record) return;
      setTitle(record.title);
      setIngredientsText(record.ingredients.join("\n"));
      setCookingMinutesText(String(record.cookingMinutes));
      setFavorite(record.favorite);
    })();
  }, [recipeId]);

  const parsedIngredients = useMemo(
    () => ingredientsText.split("\n").map((x) => x.trim()).filter(Boolean),
    [ingredientsText],
  );

  async function onSave() {
    const minutes = Number(cookingMinutesText);
    if (!title.trim() || parsedIngredients.length === 0 || !Number.isFinite(minutes) || minutes <= 0) {
      Alert.alert("Please fill all fields", "Add a title, at least one ingredient, and valid cooking minutes.");
      return;
    }

    if (recipeId) {
      await recipesRepo.update(recipeId, {
        title: title.trim(),
        ingredients: parsedIngredients,
        cookingMinutes: minutes,
        favorite,
      });
    } else {
      await recipesRepo.create({
        title: title.trim(),
        ingredients: parsedIngredients,
        cookingMinutes: minutes,
        favorite,
      });
    }

    navigation.goBack();
  }

  async function toggleFavorite() {
    if (!recipeId) {
      setFavorite((f) => !f);
      return;
    }
    const updated = await recipesRepo.update(recipeId, { favorite: !favorite });
    setFavorite(updated.favorite);
  }

  return (
    <Screen>
      <Text style={{ fontSize: t.type.title, color: t.color.text, marginBottom: t.space.md }}>{isEdit ? "Recipe detail" : "Add recipe"}</Text>
      <Card style={{ gap: t.space.sm }}>
        <TextField label="Title" value={title} onChangeText={setTitle} />
        <TextField
          label="Ingredients (one per line)"
          value={ingredientsText}
          onChangeText={setIngredientsText}
          multiline
        />
        <TextField label="Cooking minutes" value={cookingMinutesText} onChangeText={setCookingMinutesText} />
        <View style={{ gap: t.space.sm }}>
          <Button label={favorite ? "★ Favorited (tap to unfavorite)" : "☆ Mark as favorite"} onPress={toggleFavorite} />
          <Button label="Save recipe" onPress={onSave} />
        </View>
      </Card>
    </Screen>
  );
}

