type Props = NativeStackScreenProps<RootStackParamList, "Recipes">;

const recipesRepo = createRepository(recipesCollection);

export function RecipesScreen({ navigation }: Props) {
  const t = useTheme();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");

  const loadRecipes = useCallback(async () => {
    const data = query.trim() ? await recipesRepo.search(query) : await recipesRepo.list();
    setRecipes(data);
  }, [query]);

  useEffect(() => {
    const unsub = navigation.addListener("focus", loadRecipes);
    loadRecipes();
    return unsub;
  }, [navigation, loadRecipes]);

  const parsedIngredients = useMemo(
    () => ingredientsText.split("\n").map((s) => s.trim()).filter(Boolean),
    [ingredientsText],
  );

  const addRecipe = useCallback(async () => {
    const cookingMinutes = Number(minutesText);
    if (!title.trim()) {
      Alert.alert("Missing title", "Please enter a recipe title.");
      return;
    }
    if (!Number.isFinite(cookingMinutes) || cookingMinutes <= 0) {
      Alert.alert("Invalid cooking time", "Please enter cooking minutes greater than 0.");
      return;
    }
    if (parsedIngredients.length === 0) {
      Alert.alert("Missing ingredients", "Add at least one ingredient (one per line).");
      return;
    }

    await recipesRepo.create({
      title: title.trim(),
      ingredients: parsedIngredients,
      cookingMinutes,
      favorite: false,
    });

    setTitle("");
    setIngredientsText("");
    setMinutesText("");
    setShowForm(false);
    await loadRecipes();
  }, [title, minutesText, parsedIngredients, loadRecipes]);

  return (
    <Screen scroll={false}>
      <View style={{ flex: 1, padding: t.space.lg }}>
        <Text style={{ fontSize: t.type.heading, color: t.color.text, marginBottom: t.space.md }}>Recipes</Text>
        <TextField label="Search" value={query} onChangeText={setQuery} testID="search-input" />
        {showForm ? (
          <Card style={{ marginBottom: t.space.md }}>
            <Text style={{ fontSize: t.type.title, color: t.color.text, marginBottom: t.space.md }}>Add Recipe</Text>
            <TextField label="Title" value={title} onChangeText={setTitle} testID="title-input" />
            <TextField label="Ingredients (one per line)" value={ingredientsText} onChangeText={setIngredientsText} multiline testID="ingredients-input" />
            <TextField label="Cooking minutes" value={minutesText} onChangeText={setMinutesText} testID="minutes-input" />
            <View style={{ flexDirection: "row", gap: t.space.sm }}>
              <View style={{ flex: 1 }}>
                <Button label="Save" onPress={addRecipe} testID="save-recipe" />
              </View>
              <View style={{ flex: 1 }}>
                <Button label="Cancel" onPress={() => setShowForm(false)} variant="danger" testID="cancel-recipe" />
              </View>
            </View>
          </Card>
        ) : null}

        {recipes.length === 0 ? (
          <EmptyState title="No recipes yet" body="Tap + to add your first recipe." />
        ) : (
          <View>
            {recipes.map((recipe) => (
              <ListRow
                key={recipe.id}
                title={`${recipe.favorite ? "★ " : ""}${recipe.title}`}
                subtitle={`${recipe.ingredients.length} ingredients • ${recipe.cookingMinutes} min`}
                onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}
              />
            ))}
          </View>
        )}
        <FAB onPress={() => setShowForm((v) => !v)} />
      </View>
    </Screen>
  );
}

