import { useCallback, useState } from "react";
import { Ionicons } from "@expo/vector-icons";
import { Modal, Pressable, Text, TextInput, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Button, Card, EmptyState, FAB, Screen } from "../components";
import { recipeRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

export function HomeScreen() {
  const t = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [minutes, setMinutes] = useState("20");
  const [saving, setSaving] = useState(false);

  const refresh = useCallback(async () => {
    await seed();
    const results = query.trim() ? await recipeRepository.search(query) : await recipeRepository.list();
    setRecipes(results.sort((a, b) => a.title.localeCompare(b.title)));
  }, [query]);

  useFocusEffect(useCallback(() => { void refresh(); }, [refresh]));
  const canSave = title.trim().length > 0 && Number(minutes) > 0;

  async function addRecipe() {
    if (!canSave || saving) return;
    setSaving(true);
    try {
      const recipe = await recipeRepository.create({
        title: title.trim(),
        ingredients: ingredients.split(/[,\n]/).map((item) => item.trim()).filter(Boolean),
        cookingMinutes: Math.max(1, Math.round(Number(minutes))),
        favorite: false,
        isDemo: false,
      });
      setTitle("");
      setIngredients("");
      setMinutes("20");
      setAddOpen(false);
      await refresh();
      navigation.navigate("RecipeDetail", { recipeId: recipe.id });
    } finally {
      setSaving(false);
    }
  }

  return (
    <Screen>
      <View style={{ marginBottom: t.space.lg }}>
        <Text style={{ color: t.color.muted, fontSize: t.type.small, letterSpacing: 1.5, fontWeight: "700", textTransform: "uppercase" }}>YOUR KITCHEN</Text>
        <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "800", marginTop: t.space.xs }}>Recipe box</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.body, marginTop: t.space.xs }}>A little inspiration for what’s cooking.</Text>
      </View>

      <View style={{ flexDirection: "row", alignItems: "center", backgroundColor: t.color.surface, borderWidth: 1, borderColor: t.color.line, borderRadius: t.radius.card, paddingHorizontal: t.space.md, marginBottom: t.space.lg }}>
        <Ionicons name="search-outline" size={20} color={t.color.muted} />
        <TextInput value={query} onChangeText={setQuery} placeholder="Search recipes or ingredients" placeholderTextColor={t.color.muted} accessibilityLabel="Search recipes" style={{ flex: 1, padding: t.space.md, color: t.color.text, fontSize: t.type.body }} />
        {query ? <Pressable accessibilityRole="button" accessibilityLabel="Clear search" onPress={() => setQuery("")}><Ionicons name="close-circle" size={20} color={t.color.muted} /></Pressable> : null}
      </View>

      <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: t.space.sm }}>
        <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "700" }}>All recipes</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.small }}>{recipes.length} {recipes.length === 1 ? "recipe" : "recipes"}</Text>
      </View>

      {recipes.length === 0 ? (
        <Card><EmptyState title={query ? "No matches yet" : "Your recipe box is empty"} body={query ? "Try another title or ingredient." : "Add a favorite recipe to get started."} /></Card>
      ) : recipes.map((recipe, index) => (
        <Pressable key={recipe.id} accessibilityRole="button" onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}>
          <Card style={{ marginBottom: t.space.md, padding: t.space.md }}>
            <View style={{ flexDirection: "row", alignItems: "center" }}>
              <View style={{ width: 52, height: 52, borderRadius: 16, backgroundColor: t.color.bg, alignItems: "center", justifyContent: "center", marginRight: t.space.md }}>
                <Ionicons name={index % 2 ? "leaf-outline" : "restaurant-outline"} size={25} color={t.color.accent} />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={{ color: t.color.text, fontSize: t.type.body, fontWeight: "700" }}>{recipe.title}</Text>
                <Text numberOfLines={1} style={{ color: t.color.muted, fontSize: t.type.small, marginTop: t.space.xs }}>{recipe.ingredients.slice(0, 3).join(" · ")}</Text>
                <View style={{ flexDirection: "row", alignItems: "center", marginTop: t.space.sm }}>
                  <Ionicons name="time-outline" size={14} color={t.color.muted} />
                  <Text style={{ color: t.color.muted, fontSize: t.type.small, marginLeft: 4 }}>{recipe.cookingMinutes} min</Text>
                </View>
              </View>
              {recipe.favorite ? <Ionicons name="heart" size={19} color={t.color.danger} style={{ marginLeft: t.space.sm }} /> : null}
              <Ionicons name="chevron-forward" size={18} color={t.color.muted} style={{ marginLeft: t.space.sm }} />
            </View>
          </Card>
        </Pressable>
      ))}

      <FAB onPress={() => setAddOpen(true)} testID="add-recipe" />

      <Modal visible={addOpen} animationType="slide" transparent onRequestClose={() => setAddOpen(false)}>
        <View style={{ flex: 1, justifyContent: "flex-end", backgroundColor: `${t.color.text}66` }}>
          <View style={{ backgroundColor: t.color.bg, padding: t.space.lg, paddingBottom: t.space.xl, borderTopLeftRadius: 24, borderTopRightRadius: 24 }}>
            <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: t.space.lg }}>
              <View>
                <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "800" }}>Add a recipe</Text>
                <Text style={{ color: t.color.muted, marginTop: t.space.xs }}>Save something delicious.</Text>
              </View>
              <Pressable accessibilityRole="button" accessibilityLabel="Close" onPress={() => setAddOpen(false)} style={{ padding: t.space.sm }}><Ionicons name="close" size={24} color={t.color.text} /></Pressable>
            </View>
            <FormField label="Recipe name" value={title} onChangeText={setTitle} placeholder="e.g. Sunday tomato pasta" />
            <FormField label="Ingredients" value={ingredients} onChangeText={setIngredients} placeholder="Separate ingredients with commas" multiline />
            <FormField label="Cooking time (minutes)" value={minutes} onChangeText={setMinutes} placeholder="20" keyboardType="number-pad" />
            <Button label={saving ? "Saving…" : "Save recipe"} onPress={() => void addRecipe()} disabled={!canSave || saving} />
          </View>
        </View>
      </Modal>
    </Screen>
  );
}

function FormField({ label, value, onChangeText, placeholder, multiline, keyboardType }: { label: string; value: string; onChangeText: (value: string) => void; placeholder: string; multiline?: boolean; keyboardType?: "number-pad" }) {
  const t = useTheme();
  return (
    <View style={{ marginBottom: t.space.md }}>
      <Text style={{ color: t.color.text, fontWeight: "600", marginBottom: t.space.xs }}>{label}</Text>
      <TextInput value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor={t.color.muted} multiline={multiline} keyboardType={keyboardType} style={{ color: t.color.text, backgroundColor: t.color.surface, borderWidth: 1, borderColor: t.color.line, borderRadius: t.radius.card, padding: t.space.md, minHeight: multiline ? 82 : undefined, textAlignVertical: multiline ? "top" : "center" }} />
    </View>
  );
}

