      throw error;
    });
  }
  return seedWork;
}

async function seedRecords(): Promise<void> {
  const existing = await recipeRepository.list();
  if (existing.length > 0) return;

  const demoRecipes = [
    {
      title: "Lemon ricotta pancakes",
      ingredients: ["Ricotta", "Flour", "Eggs", "Lemon zest", "Maple syrup"],
      cookingMinutes: 25,
      favorite: true,
      isDemo: true,
    },
    {
      title: "Creamy tomato orzo",
      ingredients: ["Orzo", "Cherry tomatoes", "Vegetable stock", "Cream", "Fresh basil"],
      cookingMinutes: 30,
      favorite: false,
      isDemo: true,
    },
    {
      title: "Crispy chickpea bowls",
      ingredients: ["Chickpeas", "Cucumber", "Avocado", "Tahini", "Lemon"],
      cookingMinutes: 20,
      favorite: false,
      isDemo: true,
    },
  ];

  for (const recipe of demoRecipes) {
    await recipeRepository.create(recipe);
  }
}

