              <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={22} color={recipe.favorite ? t.color.danger : t.color.accent} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={{ color: t.color.text, fontSize: t.type.body, fontWeight: "700" }}>{recipe.favorite ? "In your favorites" : "Make this a favorite"}</Text>
              <Text style={{ color: t.color.muted, fontSize: t.type.small, marginTop: 2 }}>Tap to {recipe.favorite ? "remove" : "save"} this recipe</Text>
