import { useCallback, useEffect, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import { Ionicons } from "@expo/vector-icons";
import { Button, Card, EmptyState, FAB, ListRow, Screen, TextField } from "../components";
import { useTheme } from "../theme";
import { recipeRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";

export function RecipesScreen() {
  const t = useTheme();
  const navigation = useNavigation<any>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [adding, setAdding] = useState(false);
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const results = query.trim() ? await recipeRepository.search(query) : await recipeRepository.list();
    setRecipes(results.sort((a, b) => a.title.localeCompare(b.title)));
    setLoading(false);
  }, [query]);

  useEffect(() => {
    let active = true;
    seed().then(async () => {
      if (active) await refresh();
    });
    return () => { active = false; };
  }, [refresh]);

  useFocusEffect(useCallback(() => {
    refresh();
  }, [refresh]));

  const saveRecipe = async () => {
    const cleanTitle = title.trim();
    const ingredients = ingredientsText.split("\n").map((item) => item.trim()).filter(Boolean);
    const minutes = Number.parseInt(minutesText, 10);
    if (!cleanTitle || ingredients.length === 0 || !Number.isFinite(minutes) || minutes < 1) return;
    await recipeRepository.create({ title: cleanTitle, ingredients, cookingMinutes: minutes, favorite: false });
    setTitle("");
    setIngredientsText("");
    setMinutesText("");
    setAdding(false);
    await refresh();
  };

  const canSave = title.trim().length > 0 && ingredientsText.trim().length > 0 && Number(minutesText) > 0;

  return (
    <Screen>
      <View style={{ marginBottom: t.space.lg }}>
        <Text style={{ color: t.color.accent, fontSize: t.type.small, fontWeight: "700", letterSpacing: 1.5, textTransform: "uppercase" }}>YOUR KITCHEN</Text>
        <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "800", marginTop: t.space.xs }}>Recipe box</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.body, marginTop: t.space.xs }}>Good things, worth making again.</Text>
      </View>

      <TextField label="Search recipes" value={query} onChangeText={setQuery} testID="recipe-search" />

      {adding ? (
        <Card style={{ marginBottom: t.space.lg }}>
          <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "700", marginBottom: t.space.md }}>Add a recipe</Text>
          <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title-input" />
          <TextField label="Ingredients (one per line)" value={ingredientsText} onChangeText={setIngredientsText} multiline testID="recipe-ingredients-input" />
          <TextField label="Cooking time · minutes" value={minutesText} onChangeText={setMinutesText} testID="recipe-minutes-input" />
          <Button label="Save recipe" onPress={saveRecipe} disabled={!canSave} testID="save-recipe" />
          <Pressable onPress={() => setAdding(false)} style={{ alignItems: "center", paddingTop: t.space.md }}>
            <Text style={{ color: t.color.muted, fontSize: t.type.body }}>Cancel</Text>
          </Pressable>
        </Card>
      ) : null}

      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: t.space.sm }}>
        <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "700" }}>All recipes</Text>
        <Text style={{ color: t.color.muted, fontSize: t.type.small }}>{recipes.length} {recipes.length === 1 ? "recipe" : "recipes"}</Text>
      </View>

      {loading ? <Text style={{ color: t.color.muted, paddingVertical: t.space.lg }}>Gathering your recipes…</Text> : recipes.length ? (
        <Card style={{ paddingTop: t.space.xs, paddingBottom: t.space.xs }}>
          {recipes.map((recipe) => (
            <Pressable key={recipe.id} onPress={() => navigation.navigate("RecipeDetail", { id: recipe.id })}>
              <View style={{ flexDirection: "row", alignItems: "center" }}>
                <View style={{ flex: 1 }}>
                  <ListRow title={recipe.title} subtitle={`${recipe.cookingMinutes} min  ·  ${recipe.ingredients.length} ingredients`} />
                </View>
                {recipe.favorite ? <Ionicons name="heart" size={18} color={t.color.accent} style={{ marginLeft: t.space.sm, marginRight: t.space.xs }} /> : null}
                <Ionicons name="chevron-forward" size={18} color={t.color.muted} />
              </View>
            </Pressable>
          ))}
        </Card>
      ) : (
        <EmptyState title={query ? "No recipes found" : "Your recipe box is empty"} body={query ? "Try another search." : "Save a favorite to get your collection started."} />
      )}

      {!adding ? <FAB onPress={() => setAdding(true)} testID="add-recipe" /> : null}
    </Screen>
  );
}

