        <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={21} color={recipe.favorite ? t.color.danger : t.color.accent} />
        <Text style={{ color: t.color.text, fontSize: t.type.body, fontWeight: "600", marginLeft: t.space.sm }}>{recipe.favorite ? "Remove from favorites" : "Add to favorites"}</Text>
      </Pressable>
    </Screen>
  );
}

