                  {recipe.favorite ? <Ionicons name="heart" size={18} color={t.color.accent} style={{ marginLeft: t.space.sm }} /> : <Ionicons name="chevron-forward" size={18} color={t.color.muted} />}
                </View>
              </Card>
            </Pressable>
          ))}
        </View>
      )}

      <FAB onPress={() => setAddOpen(true)} testID="add-recipe" />

      <Modal visible={addOpen} animationType="slide" presentationStyle="pageSheet" onRequestClose={() => setAddOpen(false)}>
        <Screen>
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: t.space.lg }}>
            <View>
              <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "800" }}>New recipe</Text>
              <Text style={{ color: t.color.muted, marginTop: t.space.xs }}>Save something delicious.</Text>
            </View>
            <Pressable accessibilityLabel="Close" onPress={() => setAddOpen(false)} style={{ padding: t.space.sm }}><Ionicons name="close" size={24} color={t.color.text} /></Pressable>
          </View>
          <TextField label="Recipe name" value={title} onChangeText={setTitle} testID="recipe-title" />
          <TextField label="Ingredients · one per line" value={ingredientsText} onChangeText={setIngredientsText} multiline testID="recipe-ingredients" />
          <TextField label="Cooking time (minutes)" value={minutesText} onChangeText={setMinutesText} testID="recipe-minutes" />
          <Button label={saving ? "Saving…" : "Save recipe"} onPress={() => void saveRecipe()} disabled={!canSave || saving} />
        </Screen>
      </Modal>
    </Screen>
  );
}

