import { useCallback, useRef, useState } from "react";
import { ActivityIndicator, Text, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Card, EmptyState, FAB, ListRow, Screen, TextField } from "../components";
import { recipesRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

export function RecipesScreen() {
  const theme = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const requestId = useRef(0);

  const loadRecipes = useCallback(async (search: string) => {
    const request = ++requestId.current;
    try {
      await seed();
      const results = await recipesRepository.search(search);
      if (request === requestId.current) setRecipes(results.sort((a, b) => a.title.localeCompare(b.title)));
    } finally {
      if (request === requestId.current) setLoading(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      void loadRecipes(query);
    }, [loadRecipes, query]),
  );

  return (
    <Screen>
      <View style={{ marginBottom: theme.space.lg }}>
        <Text style={{ color: theme.color.text, fontSize: theme.type.heading, fontWeight: "800" }}>Your recipe box</Text>
        <Text style={{ color: theme.color.muted, fontSize: theme.type.body, marginTop: theme.space.xs }}>
          Good things to make, all in one place.
        </Text>
      </View>
      <TextField label="Search recipes" value={query} onChangeText={setQuery} testID="recipe-search" />
      {loading && recipes.length === 0 ? (
        <ActivityIndicator color={theme.color.accent} style={{ marginTop: theme.space.xl }} />
      ) : recipes.length === 0 ? (
        <Card>
          <EmptyState
            title={query ? "No recipes found" : "Your recipe box is empty"}
            body={query ? "Try another ingredient or recipe name." : "Tap + to add your first recipe."}
          />
        </Card>
      ) : (
        <Card>
          {recipes.map((recipe) => (
            <ListRow
              key={recipe.id}
              title={`${recipe.favorite ? "♥  " : ""}${recipe.title}`}
              subtitle={`${recipe.cookingMinutes} min  ·  ${recipe.ingredients.length} ingredients`}
              onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}
              testID={`recipe-${recipe.id}`}
            />
          ))}
        </Card>
      )}
      <FAB onPress={() => navigation.navigate("RecipeDetail", {})} testID="add-recipe" />
    </Screen>
  );
}

