import { useEffect, useState } from "react";
import { Alert, Pressable, Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Button, Card, EmptyState, Screen, TextField } from "../components";
import { recipesRepository, type Recipe } from "../data/models";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

 type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

export function RecipeDetailScreen({ navigation, route }: Props) {
  const theme = useTheme();
  const recipeId = route.params.recipeId;
  const isNew = !recipeId;
  const [recipe, setRecipe] = useState<Recipe | undefined>();
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!recipeId) return;
    let active = true;
    recipesRepository.get(recipeId).then((found) => {
      if (active && found) setRecipe(found);
    });
    return () => { active = false; };
  }, [recipeId]);

  const ingredients = ingredientsText
    .split(/[\n,]/)
    .map((item) => item.trim())
    .filter(Boolean);
  const minutes = Number.parseInt(minutesText, 10);
  const canSave = title.trim().length > 0 && ingredients.length > 0 && Number.isFinite(minutes) && minutes > 0;

  async function saveRecipe() {
    if (!canSave || saving) return;
    setSaving(true);
    try {
      await recipesRepository.create({
        title: title.trim(),
        ingredients,
        cookingMinutes: minutes,
        favorite: false,
        isDemo: false,
      });
      navigation.goBack();
    } catch {
      Alert.alert("Couldn't save recipe", "Please try again.");
      setSaving(false);
    }
  }

  async function toggleFavorite() {
    if (!recipe) return;
    const updated = await recipesRepository.update(recipe.id, { favorite: !recipe.favorite });
    setRecipe(updated);
  }

  if (isNew) {
    return (
      <Screen>
        <Text style={{ color: theme.color.text, fontSize: theme.type.heading, fontWeight: "800", marginBottom: theme.space.lg }}>
          Add a recipe
        </Text>
        <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title" />
        <TextField
          label="Ingredients (one per line or comma-separated)"
          value={ingredientsText}
          onChangeText={setIngredientsText}
          multiline
          testID="recipe-ingredients"
        />
        <TextField label="Cooking time (minutes)" value={minutesText} onChangeText={setMinutesText} testID="recipe-minutes" />
        <Button label={saving ? "Saving…" : "Save recipe"} onPress={() => void saveRecipe()} disabled={!canSave || saving} testID="save-recipe" />
      </Screen>
    );
  }

  if (!recipe) {
    return (
      <Screen>
        <EmptyState title="Loading recipe…" />
      </Screen>
    );
  }

  return (
    <Screen>
      <View style={{ marginBottom: theme.space.xl }}>
        <Text style={{ color: theme.color.text, fontSize: theme.type.heading, fontWeight: "800" }}>{recipe.title}</Text>
        <Text style={{ color: theme.color.muted, fontSize: theme.type.body, marginTop: theme.space.sm }}>
          Ready in {recipe.cookingMinutes} minutes
        </Text>
      </View>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={recipe.favorite ? "Remove from favorites" : "Add to favorites"}
        onPress={() => void toggleFavorite()}
        style={{ flexDirection: "row", alignItems: "center", alignSelf: "flex-start", paddingVertical: theme.space.sm, marginBottom: theme.space.lg }}
      >
        <Text style={{ color: recipe.favorite ? theme.color.danger : theme.color.accent, fontSize: 20, marginRight: theme.space.sm }}>
          {recipe.favorite ? "♥" : "♡"}
        </Text>
        <Text style={{ color: theme.color.text, fontSize: theme.type.body, fontWeight: "600" }}>
          {recipe.favorite ? "Favorited" : "Add to favorites"}
        </Text>
      </Pressable>
      <Card>
        <Text style={{ color: theme.color.text, fontSize: theme.type.title, fontWeight: "700", marginBottom: theme.space.md }}>Ingredients</Text>
        {recipe.ingredients.map((ingredient, index) => (
          <View key={`${index}-${ingredient}`} style={{ flexDirection: "row", paddingVertical: theme.space.sm, borderBottomWidth: index === recipe.ingredients.length - 1 ? 0 : 1, borderColor: theme.color.line }}>
            <Text style={{ color: theme.color.accent, marginRight: theme.space.md }}>•</Text>
            <Text style={{ color: theme.color.text, fontSize: theme.type.body, flex: 1 }}>{ingredient}</Text>
          </View>
        ))}
      </Card>
    </Screen>
  );
}

