import { useCallback, useEffect, useState } from "react";
import { Alert, Modal, Pressable, Text, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Button, Card, EmptyState, FAB, Screen, TextField } from "../components";
import { recipesRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import { useTheme } from "../theme";
import type { RootStackParamList } from "../navigation";

export function RecipesScreen() {
  const t = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [query, setQuery] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState("");
  const [ingredientsText, setIngredientsText] = useState("");
  const [minutesText, setMinutesText] = useState("");

  const loadRecipes = useCallback(async (search = query) => {
    const matching = await recipesRepository.search(search);
    setRecipes(matching.sort((a, b) => a.title.localeCompare(b.title)));
  }, [query]);

  useFocusEffect(
    useCallback(() => {
      let active = true;
      void (async () => {
        await seed();
        const matching = await recipesRepository.search(query);
        if (active) setRecipes(matching.sort((a, b) => a.title.localeCompare(b.title)));
      })();
      return () => { active = false; };
    }, [query]),
  );

  useEffect(() => {
    void loadRecipes(query);
  }, [query, loadRecipes]);

  const resetForm = () => {
    setTitle("");
    setIngredientsText("");
    setMinutesText("");
    setShowForm(false);
  };

  const saveRecipe = async () => {
    const ingredients = ingredientsText.split("\n").map((item) => item.trim()).filter(Boolean);
    const minutes = Number(minutesText);
    if (!title.trim() || ingredients.length === 0 || !Number.isFinite(minutes) || minutes <= 0) {
      Alert.alert("A little more to add", "Enter a title, at least one ingredient, and cooking time in minutes.");
      return;
    }
    await recipesRepository.create({ title: title.trim(), ingredients, cookingMinutes: Math.round(minutes), favorite: false });
    resetForm();
    await loadRecipes();
  };

  return (
    <Screen>
      <View style={{ marginBottom: t.space.md }}>
        <Text style={{ color: t.color.muted, fontSize: t.type.small, marginBottom: t.space.xs }}>YOUR COLLECTION</Text>
        <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "700" }}>Recipes</Text>
      </View>
      <TextField label="Search your recipes" value={query} onChangeText={setQuery} testID="recipe-search" />

      {recipes.length === 0 ? (
        <Card>
          <EmptyState title={query ? "No recipes found" : "Your recipe box is empty"} body={query ? "Try another title or ingredient." : "Tap + to save your first recipe."} />
        </Card>
      ) : (
        <Card style={{ paddingVertical: t.space.xs }}>
          {recipes.map((recipe, index) => (
            <Pressable
              key={recipe.id}
              onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })}
              accessibilityRole="button"
              accessibilityLabel={`Open ${recipe.title}`}
              style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: t.space.md, paddingVertical: t.space.md, borderBottomWidth: index === recipes.length - 1 ? 0 : 1, borderColor: t.color.line }}
            >
              <View style={{ flex: 1 }}>
                <Text style={{ color: t.color.text, fontSize: t.type.body }}>{recipe.title}</Text>
                <Text style={{ color: t.color.muted, fontSize: t.type.small, marginTop: t.space.xs }}>{recipe.cookingMinutes} min · {recipe.ingredients.length} ingredients</Text>
              </View>
              {recipe.favorite ? <Text style={{ color: t.color.accent, fontSize: 20, marginLeft: t.space.md }}>♥</Text> : null}
            </Pressable>
          ))}
        </Card>
      )}

      <FAB onPress={() => setShowForm(true)} testID="add-recipe" />

      <Modal visible={showForm} animationType="slide" onRequestClose={resetForm}>
        <Screen>
          <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: t.space.lg }}>
            <Text style={{ color: t.color.text, fontSize: t.type.heading, fontWeight: "700" }}>New recipe</Text>
            <Pressable onPress={resetForm} accessibilityRole="button" accessibilityLabel="Close">
              <Text style={{ color: t.color.accent, fontSize: t.type.body }}>Cancel</Text>
            </Pressable>
          </View>
          <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title" />
          <TextField label="Ingredients · one per line" value={ingredientsText} onChangeText={setIngredientsText} multiline testID="recipe-ingredients" />
