import { useCallback, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { useFocusEffect, useRoute, type RouteProp } from "@react-navigation/native";
import { Card, EmptyState, Screen } from "../components";
import { recipesRepository, type Recipe } from "../data/models";
import type { RootStackParamList } from "../navigation";
import { useTheme } from "../theme";

export function RecipeDetailScreen() {
  const t = useTheme();
  const route = useRoute<RouteProp<RootStackParamList, "RecipeDetail">>();
  const [recipe, setRecipe] = useState<Recipe | undefined>();

  useFocusEffect(
    useCallback(() => {
      let active = true;
      void recipesRepository.get(route.params.recipeId).then((item) => {
        if (active) setRecipe(item);
      });
      return () => { active = false; };
    }, [route.params.recipeId]),
  );

  const toggleFavorite = async () => {
