        <Text style={{ color: t.color.text, fontSize: t.type.body }}>{recipe.favorite ? "Favorited" : "Add to favorites"}</Text>
      </Pressable>

      <Card>
        <Text style={{ color: t.color.text, fontSize: t.type.title, fontWeight: "700", marginBottom: t.space.sm }}>Ingredients</Text>
