import { recipeRepository } from "./models";

let seedPromise: Promise<void> | undefined;

export function seed(): Promise<void> {
  if (!seedPromise) {
    seedPromise = (async () => {
      const existing = await recipeRepository.list();
      if (existing.length > 0) return;
      const demos = [
        { title: "Lemon & basil pasta", ingredients: ["200 g spaghetti", "1 lemon, zested and juiced", "2 tbsp olive oil", "2 cloves garlic, minced", "A handful of fresh basil", "40 g grated Parmesan", "Salt and black pepper"], cookingMinutes: 20, favorite: true },
        { title: "Roasted tomato soup", ingredients: ["800 g ripe tomatoes", "1 yellow onion, quartered", "3 cloves garlic", "2 tbsp olive oil", "500 ml vegetable stock", "A handful of fresh basil", "Salt and black pepper"], cookingMinutes: 45, favorite: false },
        { title: "Blueberry pancakes", ingredients: ["150 g plain flour", "2 tsp baking powder", "1 tbsp sugar", "1 egg", "200 ml milk", "100 g blueberries", "Butter, for the pan", "Maple syrup, to serve"], cookingMinutes: 25, favorite: false },
      ];
      for (const recipe of demos) await recipeRepository.create({ ...recipe, isDemo: true });
    })().catch((error: unknown) => { seedPromise = undefined; throw error; });
  }
  return seedPromise;
}

