import { useEffect, useState } from "react";
import { ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, ScrollView, Text, View } from "react-native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Ionicons } from "@expo/vector-icons";
import { Button, Card, EmptyState, Screen, TextField } from "../components";
import { recipeRepository, type Recipe } from "../data/models";
import { useTheme } from "../theme";
import type { RootStackParamList } from "../navigation";

type Props = NativeStackScreenProps<RootStackParamList, "RecipeDetail">;

export function RecipeDetailScreen({ navigation, route }: Props) {
  const t = useTheme();
  const id = route.params.recipeId;
  const isNew = !id;
  const [recipe, setRecipe] = useState<Recipe>();
  const [loading, setLoading] = useState(Boolean(id));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [title, setTitle] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [minutes, setMinutes] = useState("");
  const [checked, setChecked] = useState<number[]>([]);

  useEffect(() => {
    if (!id) return;
    let active = true;
    recipeRepository.get(id).then((record) => { if (active) setRecipe(record); })
      .catch(() => { if (active) setError("Couldn't load this recipe. Please try again."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [id]);

  async function save() {
    const items = ingredients.split("\n").map((item) => item.trim()).filter(Boolean);
    const cookingMinutes = Number(minutes.trim());
    if (!title.trim()) { setError("Give your recipe a title."); return; }
    if (!items.length) { setError("Add at least one ingredient, one per line."); return; }
    if (!minutes.trim() || !Number.isSafeInteger(cookingMinutes) || cookingMinutes < 1) { setError("Enter cooking time as a positive whole number of minutes."); return; }
    setBusy(true);
    setError("");
    try {
      const created = await recipeRepository.create({ title: title.trim(), ingredients: items, cookingMinutes, favorite: false });
      navigation.replace("RecipeDetail", { recipeId: created.id });
    } catch { setError("Couldn't save your recipe. Please try again."); }
    finally { setBusy(false); }
  }

  async function toggleFavorite() {
    if (!recipe || busy) return;
    setBusy(true);
    setError("");
    try { setRecipe(await recipeRepository.update(recipe.id, { favorite: !recipe.favorite })); }
    catch { setError("Couldn't update your favorite. Please try again."); }
    finally { setBusy(false); }
  }

  return (
    <Screen scroll={false} testID="recipe-detail-screen">
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
        <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ padding: t.space.xl, paddingBottom: 40 }}>
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 28 }}>
            <Pressable accessibilityRole="button" accessibilityLabel="Back to recipes" onPress={() => navigation.goBack()} style={{ flexDirection: "row", alignItems: "center", gap: 7, paddingVertical: 8 }}>
              <Ionicons name="arrow-back" size={21} color={t.color.text} />
              <Text style={{ color: t.color.text, fontSize: 14, fontWeight: "600" }}>Recipes</Text>
            </Pressable>
            <Text style={{ color: t.color.accent, fontSize: 10, letterSpacing: 1.8, fontWeight: "800" }}>THE RECIPE BOX</Text>
          </View>
          {isNew ? (
            <>
              <View style={{ width: 56, height: 56, borderRadius: 16, backgroundColor: t.color.surface, borderWidth: 1, borderColor: t.color.line, alignItems: "center", justifyContent: "center", marginBottom: 20 }}><Ionicons name="create-outline" size={27} color={t.color.accent} /></View>
              <Text style={{ color: t.color.text, fontSize: 32, letterSpacing: -1, fontWeight: "800" }}>Something delicious.</Text>
              <Text style={{ color: t.color.muted, fontSize: 15, lineHeight: 23, marginTop: 10, marginBottom: 28 }}>Save a new recipe to your collection. Future you will thank you.</Text>
              <Card style={{ marginBottom: 20 }}>
                <TextField label="Recipe title" value={title} onChangeText={setTitle} testID="recipe-title" />
                <TextField label="Cooking time (minutes)" value={minutes} onChangeText={setMinutes} testID="recipe-minutes" />
                <TextField label="Ingredients · one per line" value={ingredients} onChangeText={setIngredients} multiline testID="recipe-ingredients" />
                <Text style={{ color: t.color.muted, fontSize: 12, lineHeight: 19 }}>Include quantities, like “2 tbsp olive oil”, so everything is ready when you are.</Text>
              </Card>
              {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: 16, lineHeight: 21 }}>{error}</Text> : null}
              <Button label={busy ? "Saving…" : "Save recipe"} onPress={() => { void save(); }} disabled={busy} testID="save-recipe" />
            </>
          ) : loading ? <ActivityIndicator color={t.color.accent} /> : !recipe ? <EmptyState title="Recipe unavailable" body={error || "This recipe could not be found. Go back to your collection."} /> : (
            <>
              <Card style={{ alignItems: "center", paddingVertical: 32, marginBottom: 26 }}>
                <View style={{ width: 92, height: 92, borderRadius: t.radius.pill, backgroundColor: t.color.bg, alignItems: "center", justifyContent: "center", marginBottom: 18 }}>
                  <Ionicons name={recipe.title.toLowerCase().includes("pancake") ? "sunny-outline" : recipe.title.toLowerCase().includes("soup") ? "flame-outline" : "restaurant-outline"} size={42} color={t.color.accent} />
                </View>
                <Text style={{ color: t.color.accent, fontSize: 10, letterSpacing: 2, fontWeight: "800" }}>{recipe.isDemo ? "FROM OUR KITCHEN" : "FROM YOUR KITCHEN"}</Text>
                <Text style={{ color: t.color.text, fontSize: 30, fontWeight: "800", letterSpacing: -0.8, textAlign: "center", lineHeight: 36, marginTop: 12, marginBottom: 18 }}>{recipe.title}</Text>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 7 }}>
                  <Ionicons name="time-outline" size={17} color={t.color.muted} />
                  <Text style={{ color: t.color.muted, fontSize: 13 }}>{recipe.cookingMinutes} minutes</Text>
                  <Text style={{ color: t.color.line, marginHorizontal: 5 }}>|</Text>
                  <Text style={{ color: t.color.muted, fontSize: 13 }}>{recipe.ingredients.length} ingredients</Text>
                </View>
              </Card>
              <Pressable accessibilityRole="button" accessibilityLabel={recipe.favorite ? "Remove from favorites" : "Add to favorites"} accessibilityState={{ selected: recipe.favorite, disabled: busy }} testID="toggle-favorite" disabled={busy} onPress={() => { void toggleFavorite(); }} style={{ flexDirection: "row", justifyContent: "center", alignItems: "center", gap: 9, borderWidth: 1, borderColor: recipe.favorite ? t.color.accent : t.color.line, borderRadius: t.radius.card, backgroundColor: t.color.surface, paddingVertical: 14, marginBottom: 30, opacity: busy ? 0.5 : 1 }}>
                <Ionicons name={recipe.favorite ? "heart" : "heart-outline"} size={20} color={t.color.accent} />
                <Text style={{ color: t.color.accent, fontSize: 14, fontWeight: "700" }}>{recipe.favorite ? "Saved to favorites" : "Add to favorites"}</Text>
              </Pressable>
              {error ? <Text accessibilityRole="alert" style={{ color: t.color.danger, marginBottom: 16 }}>{error}</Text> : null}
              <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                <Text style={{ color: t.color.text, fontSize: 23, fontWeight: "700", letterSpacing: -0.6 }}>Ingredients</Text>
                <Text style={{ color: t.color.muted, fontSize: 12 }}>{checked.length} / {recipe.ingredients.length} ready</Text>
              </View>
              <Text style={{ color: t.color.muted, fontSize: 13, marginBottom: 18 }}>Tap to check off what you have.</Text>
              <Card style={{ paddingVertical: 2 }}>
                {recipe.ingredients.map((ingredient, index) => {
                  const selected = checked.includes(index);
                  return (
                    <Pressable key={index} accessibilityRole="checkbox" accessibilityState={{ checked: selected }} accessibilityLabel={ingredient} onPress={() => setChecked((previous) => selected ? previous.filter((item) => item !== index) : [...previous, index])} style={{ flexDirection: "row", alignItems: "center", gap: 13, paddingVertical: 17, borderBottomWidth: index < recipe.ingredients.length - 1 ? 1 : 0, borderBottomColor: t.color.line }}>
                      <Ionicons name={selected ? "checkmark-circle" : "ellipse-outline"} size={23} color={selected ? t.color.accent : t.color.line} />
                      <Text style={{ flex: 1, fontSize: 15, lineHeight: 22, color: selected ? t.color.muted : t.color.text, textDecorationLine: selected ? "line-through" : "none" }}>{ingredient}</Text>
                    </Pressable>
                  );
                })}
              </Card>
              <View style={{ alignItems: "center", marginTop: 28, gap: 8 }}>
                <Ionicons name="leaf-outline" size={19} color={t.color.accent} />
                <Text style={{ color: t.color.muted, fontSize: 12 }}>Made to be shared. Kept to be made again.</Text>
              </View>
            </>
          )}
        </ScrollView>
      </KeyboardAvoidingView>
    </Screen>
  );
}

