import { useCallback, useState } from "react";
import { ActivityIndicator, Pressable, ScrollView, Text, View } from "react-native";
import { useFocusEffect, useNavigation } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { Ionicons } from "@expo/vector-icons";
import { Card, EmptyState, Screen } from "../components";
import { useTheme } from "../theme";
import { recipeRepository, type Recipe } from "../data/models";
import { seed } from "../data/seed";
import type { RootStackParamList } from "../navigation";

export function FavoritesScreen() {
  const t = useTheme();
  const navigation = useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useFocusEffect(useCallback(() => {
    let active = true;
    setLoading(true);
    seed().then(() => recipeRepository.list()).then((records) => {
      if (active) {
        setRecipes(records.filter((recipe) => recipe.favorite));
        setError("");
      }
    }).catch(() => {
      if (active) setError("Couldn't load your favorites. Please try again.");
    }).finally(() => {
      if (active) setLoading(false);
    });
    return () => { active = false; };
  }, []));

  return (
    <Screen scroll={false} testID="favorites-screen">
      <ScrollView contentContainerStyle={{ padding: t.space.xl, paddingBottom: 40 }}>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 9, marginBottom: 24 }}>
          <Ionicons name="heart" size={21} color={t.color.accent} />
          <Text style={{ color: t.color.text, fontSize: 30, fontWeight: "800", letterSpacing: -0.8 }}>Favorites</Text>
        </View>
        <Text style={{ color: t.color.muted, fontSize: 15, lineHeight: 22, marginBottom: 24 }}>Recipes you love, ready to make again.</Text>
        {loading ? <ActivityIndicator color={t.color.accent} /> : error ? <EmptyState title="Something went wrong" body={error} /> : recipes.length === 0 ? <EmptyState title="No favorites yet" body="Tap the heart on a recipe to keep it here." /> : recipes.map((recipe, index) => (
          <Pressable key={recipe.id} accessibilityRole="button" accessibilityLabel={`Open ${recipe.title}`} onPress={() => navigation.navigate("RecipeDetail", { recipeId: recipe.id })} style={{ marginBottom: 12 }}>
            <Card style={{ padding: 16 }}>
              <View style={{ flexDirection: "row", alignItems: "center", gap: 14 }}>
                <View style={{ width: 64, height: 78, backgroundColor: t.color.bg, borderRadius: 10, alignItems: "center", justifyContent: "center", gap: 7 }}>
                  <Ionicons name={recipe.title.toLowerCase().includes("pancake") ? "sunny-outline" : recipe.title.toLowerCase().includes("soup") ? "flame-outline" : "restaurant-outline"} size={28} color={t.color.accent} />
                  <Text style={{ color: t.color.muted, fontSize: 9, fontWeight: "600", letterSpacing: 1 }}>FAVORITE {String(index + 1).padStart(2, "0")}</Text>
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: t.color.text, fontSize: 17, fontWeight: "700", lineHeight: 23 }} numberOfLines={2}>{recipe.title}</Text>
                  <View style={{ flexDirection: "row", alignItems: "center", marginTop: 10, gap: 5 }}>
                    <Ionicons name="time-outline" size={14} color={t.color.muted} />
                    <Text style={{ color: t.color.muted, fontSize: 12 }}>{recipe.cookingMinutes} min  ·  {recipe.ingredients.length} ingredients</Text>
                  </View>
                </View>
                <View style={{ gap: 20, alignItems: "center" }}>
                  <Ionicons name="heart" size={17} color={t.color.accent} />
                  <Ionicons name="chevron-forward" size={17} color={t.color.muted} />
                </View>
              </View>
            </Card>
          </Pressable>
        ))}
      </ScrollView>
    </Screen>
  );
}
